import 'dart:convert';
import 'dart:io';
import 'package:flutter_test/flutter_test.dart';
import 'package:seguimiento/ui/exercise_figure_3d.dart' as current;
import 'package:seguimiento/ui/exercise_figure_3d_view.dart' as view;
import 'exercise_figure_3d_pre_exact.dart' as previous;

void main() {
  test('diagnose geometric limit versus playback-time continuity before and after exact extension', () {
    final source = File(current.Figure3DCatalog.asset).readAsStringSync();
    final now = current.Figure3DCatalog.fromJsonString(source).forExercise('Burpees')!;
    final old = previous.Figure3DCatalog.fromJsonString(source).forExercise('Burpees')!;
    final rows = <Map<String, Object>>[];
    for (final key in [4, 5]) {
      final time = now.motion.take(key).fold<double>(0, (sum, stage) => sum + stage.seconds);
      for (final epsilon in [1e-4, 1e-6, 1e-8, 1e-10]) {
        final a = (key - epsilon) / now.motion.length;
        final b = (key + epsilon) / now.motion.length;
        final ca = current.liftSkeleton(now.skeletonAt(a), now).p['nearKnee']!;
        final cb = current.liftSkeleton(now.skeletonAt(b), now).p['nearKnee']!;
        final oa = previous.liftSkeleton(old.skeletonAt(a), old).p['nearKnee']!;
        final ob = previous.liftSkeleton(old.skeletonAt(b), old).p['nearKnee']!;
        final ta = view.figureMotionProgress(now, time - epsilon);
        final tb = view.figureMotionProgress(now, time + epsilon);
        final cta = current.liftSkeleton(now.skeletonAt(ta), now).p['nearKnee']!;
        final ctb = current.liftSkeleton(now.skeletonAt(tb), now).p['nearKnee']!;
        final ota = previous.liftSkeleton(old.skeletonAt(ta), old).p['nearKnee']!;
        final otb = previous.liftSkeleton(old.skeletonAt(tb), old).p['nearKnee']!;
        rows.add({'key': key, 'epsilon': epsilon, 'currentGeometricDelta': (cb-ca).length,
          'oldGeometricDelta': (ob-oa).length, 'currentPlaybackDelta': (ctb-cta).length,
          'oldPlaybackDelta': (otb-ota).length});
      }
    }
    File('docs/context/sessions/035-evidence/continuity-diagnostic.json')
      .writeAsStringSync(const JsonEncoder.withIndent('  ').convert(rows));
    for (final row in rows) { print(jsonEncode(row)); }
    expect(rows.length, 8);
  });
}
